import{_ as o,o as t,c as l,a0 as r}from"./chunks/framework.CBux2OW7.js";const p=JSON.parse('{"title":"Public Facing Controllers","description":"","frontmatter":{},"headers":[],"relativePath":"backend/controllers/public-facing.md","filePath":"backend/controllers/public-facing.md"}'),a={name:"backend/controllers/public-facing.md"};function c(i,e,n,s,d,h){return t(),l("div",null,[...e[0]||(e[0]=[r('<h1 id="public-facing-controllers" tabindex="-1">Public Facing Controllers <a class="header-anchor" href="#public-facing-controllers" aria-label="Permalink to &quot;Public Facing Controllers&quot;">​</a></h1><p>These controllers handle all unauthenticated traffic hitting the TechyNews platform. Their primary responsibility is fetching data efficiently and passing it to the Inertia frontend.</p><h2 id="welcomecontroller" tabindex="-1"><code>WelcomeController</code> <a class="header-anchor" href="#welcomecontroller" aria-label="Permalink to &quot;`WelcomeController`&quot;">​</a></h2><p>Serves the homepage (<code>/</code>).</p><ul><li>Queries the <code>Article</code> model for the latest published articles.</li><li>May include specific logic to isolate the <code>editorsChoice</code> (hero) article from the rest of the grid.</li><li><strong>Performance:</strong> Relies on eager loading (<code>with([&#39;category&#39;, &#39;tags&#39;])</code>) to prevent N+1 queries on the homepage grid.</li></ul><h2 id="archivecontroller" tabindex="-1"><code>ArchiveController</code> <a class="header-anchor" href="#archivecontroller" aria-label="Permalink to &quot;`ArchiveController`&quot;">​</a></h2><p>Serves the historical feed (<code>/archive</code>).</p><ul><li>Implements Laravel&#39;s <code>paginate()</code> method.</li><li>Passes the pagination meta-data directly to Inertia so the React frontend can build the &quot;Next/Previous&quot; buttons or infinite scroll.</li><li>Handles optional <code>?search=</code> or <code>?category=</code> query parameters to filter the Eloquent query before paginating.</li></ul><h2 id="publiccontroller-aboutcontroller-contactcontroller" tabindex="-1"><code>PublicController</code>, <code>AboutController</code>, <code>ContactController</code> <a class="header-anchor" href="#publiccontroller-aboutcontroller-contactcontroller" aria-label="Permalink to &quot;`PublicController`, `AboutController`, `ContactController`&quot;">​</a></h2><p>These are simple controllers for static or semi-static pages.</p><ul><li><strong><code>AboutController</code></strong>: Renders the <code>About.jsx</code> page.</li><li><strong><code>ContactController</code></strong>: Handles form submissions from the public, typically validating the request and dispatching a Mailable.</li><li><strong><code>PublicController</code></strong>: Often acts as a catch-all or utility for generic public views (like terms and conditions if not handled by a dedicated controller).</li></ul>',11)])])}const b=o(a,[["render",c]]);export{p as __pageData,b as default};
